#include <iostream>

int main() {
    int original = 4;
    int copy = original;
    int& ref = original;
    int* ptr = &original;
    copy = 9;
    ref = 6;
    *ptr = 8;
    int other = 20;
    ptr = &other;
    *ptr = 21;
    std::cout << original << ' ' << copy << ' ' << ref << ' ' << other << '\n';
    return 0;
}

